I think I can see an issue with the WebSocketsTransport, would it be possible for you to try an experiment where you replace the WebSocket implementation with a custom one below and when you trigger the issue (and wait more than 30 seconds) you cancel the token (also shown below)?

```csharp
var cts = new CancellationTokenSource();

new HubConnectionBuilder()
    .WithUrl(uriWithQueryString, options =>
    {
        options.WebSocketFactory = async (context, _) =>
        {
            var websocket = new WebSocketWrapper(new ClientWebSocket(), cts.Token);
            await websocket.ConnectAsync(context.Uri, CancellationToken.None);
            return websocket;
        };
    })
    ...

// after unplugging ethernet and waiting at least 30 seconds
cts.Cancel();

internal class WebSocketWrapper : WebSocket
{
    private readonly ClientWebSocket _inner;
    private readonly CancellationToken _cancellationToken;

    public WebSocketWrapper(ClientWebSocket inner, CancellationToken cancellationToken)
    {
        _inner = inner;
        _cancellationToken = cancellationToken;
    }

    public Task ConnectAsync(Uri uri, CancellationToken cancellationToken) => _inner.ConnectAsync(uri, cancellationToken);

    public override WebSocketCloseStatus? CloseStatus => _inner.CloseStatus;

    public override string CloseStatusDescription => _inner.CloseStatusDescription;

    public override WebSocketState State => _inner.State;

    public override string SubProtocol => _inner.SubProtocol;

    public override void Abort() => _inner.Abort();

    public override Task CloseAsync(WebSocketCloseStatus closeStatus, string statusDescription, CancellationToken cancellationToken)
        => _inner.CloseAsync(closeStatus, statusDescription, cancellationToken);

    public override Task CloseOutputAsync(WebSocketCloseStatus closeStatus, string statusDescription, CancellationToken cancellationToken)
        => _inner.CloseOutputAsync(closeStatus, statusDescription, _cancellationToken);

    public override void Dispose() => _inner.Dispose();

    public override Task<WebSocketReceiveResult> ReceiveAsync(ArraySegment<byte> buffer, CancellationToken cancellationToken)
        => _inner.ReceiveAsync(buffer, cancellationToken);

    public override Task SendAsync(ArraySegment<byte> buffer, WebSocketMessageType messageType, bool endOfMessage, CancellationToken cancellationToken)
        => _inner.SendAsync(buffer, messageType, endOfMessage, _cancellationToken);
}
```
